package org.sleepwell.app;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.Test;import static org.junit.Assert.*;
/** Continuous real pump/DSP through injected acoustic PCM and durable-port calls. No Android services. */
public class SonarNightTest {
 static final class Clock implements SonarNight.Clock {final AtomicLong now=new AtomicLong(100000),wallShift=new AtomicLong();public long millis(){return now.get();}public long wall(){return 1700000000000L+millis()-100000+wallShift.get();}public void idle()throws InterruptedException{if(Thread.interrupted())throw new InterruptedException();now.addAndGet(10);Thread.sleep(1);}}
 static class Audio extends SonarPumpTest.Io {final Clock clock;final Sink sink;long boot;String capture="UNPROCESSED";volatile boolean silence;Audio(Clock clock,Sink sink){this.clock=clock;this.sink=sink;}public String captureSource(){return capture;}public void startMuted(){if(sink.session==null||sink.paused)throw new IllegalStateException("Capture preceded durable admission");boot=clock.millis()*1000000L;}public SonarPump.Timing timing(){return new SonarPump.Timing(0,boot);}public int read(short[] data,int at,int count){int n=super.read(data,at,count);if(silence)Arrays.fill(data,at,at+n,(short)0);return n;}}
 static class Sink implements SonarNight.Sink {final Clock clock;volatile SonarNight.Session session;final List<SonarEpochsTest.Row> rows=new CopyOnWriteArrayList<>();final List<Long> pauses=new CopyOnWriteArrayList<>(),resumes=new CopyOnWriteArrayList<>();volatile boolean paused,closed,failed,interrupted;volatile long ended,active;Sink(Clock c){clock=c;}void thread(){if(!Thread.currentThread().getName().equals("SleepWell-sonar-storage"))throw new IllegalStateException("Storage left its ordered worker");}public SonarNight.Session begin(SonarConfig c,String capture){thread();return session=new SonarNight.Session(7,clock.wall(),clock.millis());}public void checkpoint(long id,long from,long to,Double value,String quality,int samples,long active)throws Exception{thread();if(failed)throw new IllegalStateException("Injected disk failure");rows.add(new SonarEpochsTest.Row(from,to,value,quality,samples,active));}public void pause(long id,long at){thread();paused=true;pauses.add(at);}public void resume(long id,long at){thread();paused=false;resumes.add(at);}public void end(long id,long at,long active,boolean interrupted){thread();ended=at;this.active=active;this.interrupted=interrupted;}public void close(){thread();closed=true;}}
 static void await(java.util.function.BooleanSupplier predicate)throws Exception{long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);while(!predicate.getAsBoolean()&&System.nanoTime()<deadline)Thread.sleep(10);assertTrue("Asynchronous core state",predicate.getAsBoolean());}
 @Test public void realPcmNightPauseResumeStopPreservesAnchorQualityAndActiveGap()throws Exception{Clock clock=new Clock();Sink sink=new Sink(clock);List<Audio> devices=new CopyOnWriteArrayList<>();SonarNight night=new SonarNight(SonarConfig.defaults(),(cfg,cancel)->{Audio a=new Audio(clock,sink);devices.add(a);return a;},sink,clock,Runnable::run,state->{});try{night.start();await(()->night.state().readings.stream().anyMatch(f->f.movement!=null&&f.movement>.03));night.pause();await(()->night.state().phase.equals("PAUSED"));assertTrue(devices.get(0).closed);long before=night.state().active;clock.now.addAndGet(60000);clock.wallShift.set(-3600000);assertEquals(before,night.state().active);assertTrue(night.resume());await(()->devices.size()==2&&night.state().readings.stream().anyMatch(f->f.from>60000&&f.movement!=null));night.stop(false);assertTrue(night.awaitClosed(8000));assertEquals("CLOSED",night.state().phase);assertEquals("",night.state().error);assertEquals(1,sink.pauses.size());assertEquals(1,sink.resumes.size());assertTrue(sink.resumes.get(0)-sink.pauses.get(0)>=60000);assertTrue(sink.closed);assertTrue(sink.active<20000);assertTrue(sink.ended>=1700000060000L);assertTrue(sink.rows.stream().anyMatch(r->r.value!=null));assertTrue(sink.rows.stream().anyMatch(r->r.value==null));for(SonarEpochsTest.Row r:sink.rows)assertTrue(r.to-r.from<=5000);}finally{night.stop(true);assertTrue(night.awaitClosed(8000));}}
 @Test public void realSignalLossPersistsNullRatherThanZeroAndStopRemainsResponsive()throws Exception{Clock clock=new Clock();Sink sink=new Sink(clock);AtomicReference<Audio> audio=new AtomicReference<>();SonarNight night=new SonarNight(SonarConfig.defaults(),(cfg,cancel)->{Audio a=new Audio(clock,sink);audio.set(a);return a;},sink,clock,Runnable::run,state->{});try{night.start();await(()->night.state().readings.stream().anyMatch(f->f.movement!=null));audio.get().silence=true;await(()->night.state().readings.stream().anyMatch(f->f.quality==SonarFrame.Quality.NO_ECHO));night.stop(false);assertTrue(night.awaitClosed(8000));assertTrue(sink.rows.stream().anyMatch(r->r.quality.equals("NO_ECHO")&&r.value==null));assertTrue(audio.get().closed);}finally{night.stop(true);assertTrue(night.awaitClosed(8000));}}
 @Test public void slowStorageCannotBlockAudioCancellation()throws Exception{Clock clock=new Clock();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);Sink sink=new Sink(clock){boolean first=true;public void checkpoint(long id,long from,long to,Double value,String quality,int samples,long active)throws Exception{if(first){first=false;entered.countDown();release.await();}super.checkpoint(id,from,to,value,quality,samples,active);}};AtomicReference<Audio> audio=new AtomicReference<>();SonarNight night=new SonarNight(SonarConfig.defaults(),(cfg,cancel)->{Audio a=new Audio(clock,sink);audio.set(a);return a;},sink,clock,Runnable::run,state->{});try{night.start();assertTrue(entered.await(8,TimeUnit.SECONDS));long before=System.nanoTime();night.stop(false);assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-before)<100);await(()->audio.get().closed);assertFalse(night.awaitClosed(30));release.countDown();assertTrue(night.awaitClosed(8000));}finally{release.countDown();night.stop(true);assertTrue(night.awaitClosed(8000));}}
 @Test public void diskFailureIsVisibleAndDoesNotAdvertiseSavedSuccess()throws Exception{Clock clock=new Clock();Sink sink=new Sink(clock);sink.failed=true;AtomicReference<Audio> audio=new AtomicReference<>();SonarNight night=new SonarNight(SonarConfig.defaults(),(cfg,cancel)->{Audio a=new Audio(clock,sink);audio.set(a);return a;},sink,clock,Runnable::run,state->{});night.start();assertTrue(night.awaitClosed(12000));assertTrue(night.state().error.contains("Injected disk failure"));assertTrue(sink.interrupted);assertTrue(audio.get().closed);assertTrue(sink.closed);}
 @Test public void captureSourceCannotSilentlyChangeWhenResumingSameNight()throws Exception{Clock clock=new Clock();Sink sink=new Sink(clock);AtomicInteger opens=new AtomicInteger();SonarNight night=new SonarNight(SonarConfig.defaults(),(cfg,cancel)->{Audio a=new Audio(clock,sink);if(opens.incrementAndGet()>1)a.capture="VOICE_RECOGNITION";return a;},sink,clock,Runnable::run,state->{});try{night.start();await(()->night.state().phase.equals("ACTIVE"));night.pause();await(()->night.state().phase.equals("PAUSED"));assertTrue(night.resume());assertTrue(night.awaitClosed(8000));assertTrue(night.state().error.contains("source changed"));assertTrue(sink.interrupted);assertEquals(7,sink.session.id);}finally{night.stop(true);assertTrue(night.awaitClosed(8000));}}

 @Test public void cancellationDuringBlockedAdmissionNeverStartsCaptureAndEndCannotPredateBegin()throws Exception{
  Clock clock=new Clock();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger started=new AtomicInteger();
  Sink sink=new Sink(clock){public SonarNight.Session begin(SonarConfig config,String capture){entered.countDown();boolean interrupted=false;while(true)try{release.await();break;}catch(InterruptedException e){interrupted=true;}clock.now.addAndGet(1000);SonarNight.Session value=super.begin(config,capture);if(interrupted)Thread.currentThread().interrupt();return value;}};
  AtomicReference<Audio> audio=new AtomicReference<>();SonarNight night=new SonarNight(SonarConfig.defaults(),(config,cancel)->{Audio a=new Audio(clock,sink){public void startMuted(){started.incrementAndGet();super.startMuted();}};audio.set(a);return a;},sink,clock,Runnable::run,state->{});
  try{night.start();assertTrue(entered.await(3,TimeUnit.SECONDS));night.stop(false);await(()->audio.get().closed);assertEquals(0,started.get());assertFalse(night.awaitClosed(30));release.countDown();assertTrue(night.awaitClosed(8000));assertEquals(0,started.get());assertEquals(sink.session.wall,sink.ended);assertEquals(0,sink.active);assertTrue(sink.rows.isEmpty());}finally{release.countDown();night.stop(true);assertTrue(night.awaitClosed(8000));}
 }
 @Test public void futureCaptureTimestampStopsInsteadOfFabricatingWallEvidence()throws Exception{
  Clock clock=new Clock();Sink sink=new Sink(clock);SonarNight night=new SonarNight(SonarConfig.defaults(),(config,cancel)->new Audio(clock,sink){public SonarPump.Timing timing(){return new SonarPump.Timing(0,boot+1000000000L);}},sink,clock,Runnable::run,state->{});
  night.start();assertTrue(night.awaitClosed(8000));assertTrue(night.state().error.contains("ahead of elapsed time"));assertTrue(sink.interrupted);assertTrue(sink.rows.stream().allMatch(row->row.value==null));
 }
 @Test public void failedForegroundResumeStaysPausedWithoutNewAudioAndCanRetryExplicitly()throws Exception{
  Clock clock=new Clock();Sink sink=new Sink(clock);AtomicInteger opened=new AtomicInteger();SonarNight night=new SonarNight(SonarConfig.defaults(),(config,cancel)->{opened.incrementAndGet();return new Audio(clock,sink);},sink,clock,Runnable::run,state->{});
  try{night.start();await(()->night.state().phase.equals("ACTIVE"));night.pause();await(()->night.state().phase.equals("PAUSED"));long before=night.state().active;night.resumeFailed("Microphone foreground access was revoked");assertEquals("PAUSED",night.state().phase);assertTrue(night.state().error.contains("revoked"));assertEquals(1,opened.get());assertEquals(before,night.state().active);assertTrue(night.resume());await(()->opened.get()==2&&night.state().phase.equals("ACTIVE"));assertEquals("",night.state().error);}finally{night.stop(true);assertTrue(night.awaitClosed(8000));}
 }

 @Test public void userPauseCannotOverrideDiskFailureStopWhileNativeCloseIsPending()throws Exception{
  Clock clock=new Clock();Sink sink=new Sink(clock);sink.failed=true;CountDownLatch closing=new CountDownLatch(1),release=new CountDownLatch(1);
  SonarNight night=new SonarNight(SonarConfig.defaults(),(config,cancel)->new Audio(clock,sink){public void close(){closing.countDown();boolean interrupted=false;for(;;)try{release.await();break;}catch(InterruptedException e){interrupted=true;}super.close();if(interrupted)Thread.currentThread().interrupt();}},sink,clock,Runnable::run,state->{});
  try{night.start();assertTrue(closing.await(8,TimeUnit.SECONDS));night.pause();assertFalse(night.state().phase.equals("PAUSING"));release.countDown();assertTrue(night.awaitClosed(8000));assertEquals("CLOSED",night.state().phase);assertTrue(sink.interrupted);assertTrue(sink.closed);assertTrue(night.state().error.contains("disk failure"));assertFalse(night.resume());}finally{release.countDown();night.stop(true);assertTrue(night.awaitClosed(8000));}
 }
}
